def _detect_mc_from_text(text):
    """Detect if decoded text shows multiple-choice reasoning patterns.

    Uses conservative detection: at least 2 option references to
    trigger MC mode. Only checks last 1200 chars to keep cost O(1)
    since MC patterns are local (options enumerated near current position).
    """
    if not text or len(text) < 20:
        return False

    # Only check last ~200 words = 1200 chars — MC patterns are local
    _TAIL_CHARS = 1200
    if len(text) > _TAIL_CHARS:
        text = text[-_TAIL_CHARS:]

    patterns = [
        r'\boption\s+[a-d]\b',
        r'\bOption\s+[A-D]\b',
    ]
    total = 0
    for pat in patterns:
        matches = re.findall(pat, text)
        total += len(matches)
    if total >= 2:
        return True
    enum_matches = re.findall(r'\b[A-D]\)', text)
    if len(enum_matches) >= 2:
        return True
    return False
def _truncate_words(text, max_words):
    words = text.split()
    if len(words) <= max_words:
        return text
    return " ".join(words[:max_words])


